 "content": "def transform(grid):
    """Encode the minority-color cells using the original majority color; clear the majority cells."""
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    majority = max(counts, key=counts.get)
    minority = min(counts, key=counts.get)
    return [[majority if cell == minority else 0 for cell in row] for row in grid]
